@page "/board"
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<h1 class="mb-4">Project Board</h1>

@if (_errorMessage is not null)
{
    <div class="alert alert-danger" role="alert">
        <strong>Error:</strong> @_errorMessage
    </div>
}

@if (_loading)
{
    <div class="d-flex justify-content-center my-5">
        <div class="spinner-border" role="status">
            <span class="visually-hidden">Loading...</span>
        </div>
    </div>
}
else if (_tasks is not null)
{
    <!-- Summary stats bar -->
    <div class="row g-2 mb-3">
        <div class="col">
            <div class="card text-center">
                <div class="card-body py-2">
                    <div class="fw-bold">Total</div>
                    <div class="fs-4">@FilteredTasks.Count</div>
                </div>
            </div>
        </div>
        @foreach (var col in Columns)
        {
            <div class="col">
                <div class="card text-center">
                    <div class="card-body py-2">
                        <div class="fw-bold">@col</div>
                        <div class="fs-4">@TasksForColumn(col).Count</div>
                    </div>
                </div>
            </div>
        }
        <div class="col">
            <div class="card text-center border-danger">
                <div class="card-body py-2">
                    <div class="fw-bold text-danger">Overdue</div>
                    <div class="fs-4 text-danger">@FilteredTasks.Count(t => t.DueDate < DateTime.Today)</div>
                </div>
            </div>
        </div>
    </div>

    <!-- Search bar -->
    <div class="mb-3">
        <input type="text" class="form-control" placeholder="Search tasks by title..."
               @bind="_searchText" @bind:event="oninput" />
    </div>

    <!-- Kanban columns -->
    <div class="row g-3">
        @for (var i = 0; i < Columns.Length; i++)
        {
            var colIndex = i;
            var colName = Columns[colIndex];
            var colTasks = TasksForColumn(colName);

            <div class="col-md-4">
                <div class="card h-100">
                    <div class="card-header d-flex justify-content-between align-items-center">
                        <strong>@colName</strong>
                        <span class="badge bg-secondary">@colTasks.Count</span>
                    </div>
                    <div class="card-body d-flex flex-column gap-2 p-2" style="min-height: 200px;">
                        @foreach (var task in colTasks)
                        {
                            <div class="card shadow-sm">
                                <div class="card-body p-2">
                                    <div class="fw-semibold mb-1">@task.Title</div>
                                    <div class="d-flex justify-content-between align-items-center mb-1">
                                        <small class="text-muted">@task.Assignee</small>
                                        <span class="badge @PriorityBadgeClass(task.Priority)">@task.Priority</span>
                                    </div>
                                    <div class="d-flex justify-content-between align-items-center">
                                        <small class="@(task.DueDate < DateTime.Today ? "text-danger" : "text-muted")">
                                            @task.DueDate.ToString("MMM dd")
                                        </small>
                                        <div>
                                            @if (colIndex > 0)
                                            {
                                                <button class="btn btn-outline-secondary btn-sm me-1"
                                                        @onclick="() => MoveTaskAsync(task.Id, Columns[colIndex - 1])"
                                                        disabled="@_movingTaskId.HasValue">
                                                    &larr; Move Left
                                                </button>
                                            }
                                            @if (colIndex < Columns.Length - 1)
                                            {
                                                <button class="btn btn-outline-secondary btn-sm"
                                                        @onclick="() => MoveTaskAsync(task.Id, Columns[colIndex + 1])"
                                                        disabled="@_movingTaskId.HasValue">
                                                    Move Right &rarr;
                                                </button>
                                            }
                                        </div>
                                    </div>
                                </div>
                            </div>
                        }

                        <!-- Inline add-task form -->
                        @if (_addingToColumn == colName)
                        {
                            <div class="card border-primary mt-auto">
                                <div class="card-body p-2">
                                    <input type="text" class="form-control form-control-sm mb-1"
                                           placeholder="Title" @bind="_newTitle" />
                                    <input type="text" class="form-control form-control-sm mb-1"
                                           placeholder="Assignee" @bind="_newAssignee" />
                                    <select class="form-select form-select-sm mb-1" @bind="_newPriority">
                                        <option value="High">High</option>
                                        <option value="Medium">Medium</option>
                                        <option value="Low">Low</option>
                                    </select>
                                    <input type="date" class="form-control form-control-sm mb-2"
                                           @bind="_newDueDate" />
                                    <div class="d-flex gap-1">
                                        <button class="btn btn-primary btn-sm flex-fill"
                                                @onclick="SaveNewTaskAsync" disabled="@_saving">
                                            @if (_saving)
                                            {
                                                <span class="spinner-border spinner-border-sm me-1"></span>
                                            }
                                            Save
                                        </button>
                                        <button class="btn btn-outline-secondary btn-sm flex-fill"
                                                @onclick="CancelAdd" disabled="@_saving">
                                            Cancel
                                        </button>
                                    </div>
                                </div>
                            </div>
                        }
                    </div>
                    @if (_addingToColumn != colName)
                    {
                        <div class="card-footer text-center">
                            <button class="btn btn-outline-primary btn-sm w-100"
                                    @onclick="() => StartAdd(colName)">
                                + Add Task
                            </button>
                        </div>
                    }
                </div>
            </div>
        }
    </div>
}

@code {
    private static readonly string[] Columns = ["To Do", "In Progress", "Done"];

    private List<TaskItem>? _tasks;
    private bool _loading = true;
    private string? _errorMessage;
    private string _searchText = string.Empty;

    // Move state
    private int? _movingTaskId;

    // Add-task form state
    private string? _addingToColumn;
    private string _newTitle = string.Empty;
    private string _newAssignee = string.Empty;
    private string _newPriority = "Medium";
    private DateTime _newDueDate = DateTime.Today.AddDays(7);
    private bool _saving;

    private List<TaskItem> FilteredTasks =>
        _tasks!.Where(t => t.Title.Contains(_searchText, StringComparison.OrdinalIgnoreCase)).ToList();

    private List<TaskItem> TasksForColumn(string status) =>
        FilteredTasks.Where(t => t.Status == status).ToList();

    protected override async Task OnInitializedAsync()
    {
        try
        {
            _tasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            _errorMessage = ex.Message;
        }
        finally
        {
            _loading = false;
        }
    }

    private async Task MoveTaskAsync(int taskId, string newStatus)
    {
        _movingTaskId = taskId;
        try
        {
            await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
            var idx = _tasks!.FindIndex(t => t.Id == taskId);
            if (idx >= 0)
            {
                _tasks[idx] = _tasks[idx] with { Status = newStatus };
            }
        }
        catch (Exception ex)
        {
            _errorMessage = ex.Message;
        }
        finally
        {
            _movingTaskId = null;
        }
    }

    private void StartAdd(string column)
    {
        _addingToColumn = column;
        _newTitle = string.Empty;
        _newAssignee = string.Empty;
        _newPriority = "Medium";
        _newDueDate = DateTime.Today.AddDays(7);
    }

    private void CancelAdd() => _addingToColumn = null;

    private async Task SaveNewTaskAsync()
    {
        if (string.IsNullOrWhiteSpace(_newTitle) || _addingToColumn is null)
            return;

        _saving = true;
        try
        {
            var created = await TaskService.CreateTaskAsync(_newTitle, _newAssignee, _newPriority, _newDueDate);
            // CreateTaskAsync may default to "To Do"; ensure it matches the target column
            if (created.Status != _addingToColumn)
            {
                await TaskService.UpdateTaskStatusAsync(created.Id, _addingToColumn);
                created = created with { Status = _addingToColumn };
            }
            _tasks!.Add(created);
            _addingToColumn = null;
        }
        catch (Exception ex)
        {
            _errorMessage = ex.Message;
        }
        finally
        {
            _saving = false;
        }
    }

    private static string PriorityBadgeClass(string priority) => priority switch
    {
        "High" => "bg-danger",
        "Medium" => "bg-warning text-dark",
        "Low" => "bg-success",
        _ => "bg-secondary"
    };
}

